/// One workroom pane: a title bar naming the workroom and carrying its own actions, above the full
/// terminal body, the pair wrapped in a rounded card. Identical solo and split since issue #139 — only
/// the remove-from-split ✕, its menu item, and the group-drag gesture are `multi`-only, because only a
/// real member has a group to leave or move within.
private struct WorkroomPaneLeaf: View {
  /// Plain (non-observed) store reference for the group title bar's context menu (issue #112) —
  /// see `WorkroomSplitView.store`. NOT `@EnvironmentObject`: this view hosts a live terminal and
  /// must not re-evaluate on every unrelated store change.
  let store: AppStore
  let sid: SidebarID
  let target: TerminalTarget
  let focused: Bool
  let multi: Bool
  /// The shared workroom-drag state — the title bar writes it while dragging this group (issue #110).
  @Binding var externalDrag: WorkroomPaneDrag?
  let localize: (CGPoint) -> CGPoint?
  let dropTarget: (CGPoint) -> (sid: SidebarID, edge: PaneEdge)?
  let onClose: () -> Void
  let onMove: (SidebarID, SidebarID, PaneEdge) -> Void

  var body: some View {
    // `content` MUST stay at ONE structural position (the second child of this VStack) — the title bar
    // is a *sibling* above it, never a wrapper around it. A structural
    // `if multi { VStack { titleBar; content } } else { content }` would swap SwiftUI's
    // `_ConditionalContent` branch when a 2-member split dissolves to solo, tearing down + rebuilding
    // `TargetTerminalDetail` and re-parenting the libghostty surface — the blank/stranded-pane bug.
    // This mirrors `PaneLeafView`, which keeps its content in one slot and expresses the `multiPane`
    // chrome as always-mounted overlays (issue #3).
    //
    // Since issue #139 the title bar is UNCONDITIONAL, which strengthens that invariant rather than
    // straining it: with no `if` there is no branch left to flip on this axis. The hazard of the same
    // shape that remains is the missing-directory choice, which is why `TargetTerminalDetail` owns it
    // as a ZStack sibling rather than this view branching on it.
    VStack(spacing: 0) {
      // Every workroom is identified by its own header (issue #139), which in a split also names
      // *which* member this is and offers the way back out of the group.
      WorkroomPaneTitleBar(
        target: target, projectPath: projectPath, projectLabel: projectLabel,
        workroomName: workroomName, focused: focused,
        controls: toolbarControls, onClose: onClose
      )
      // Drag the group by its title bar to move the whole member within the split (issue #110) —
      // the SAME gesture/closures the tab-bar chip uses, so it drops onto the same panes and shows
      // the same drop-edge highlight. A plain click (no movement past `minimumDistance`) still
      // falls through to the leaf's focus tap.
      //
      // `including:` MUST be `.subviews` (not `.none`) when solo: `GestureMask.none` disables every
      // gesture in the SUBVIEW hierarchy as well as the added one, which would kill this bar's own
      // Run / Open-in buttons in exactly the single-workroom case issue #139 exists to serve — and
      // `ToolbarIconButtonStyle`'s hover well is `.onHover`, not a gesture, so they would still light
      // up and look alive. `.subviews` drops only the drag.
      .gesture(
        DragGesture(minimumDistance: 6, coordinateSpace: .global)
          .onChanged { value in
            externalDrag = localize(value.location).map {
              WorkroomPaneDrag(sid: sid, location: $0)
            }
          }
          .onEnded { value in
            if let drop = dropTarget(value.location), drop.sid != sid {
              onMove(sid, drop.sid, drop.edge)
            }
            externalDrag = nil
          },
        including: multi ? .all : .subviews
      )
      // The workroom's right-click menu (issue #112) — the SAME items as the tab chip (incl.
      // "Close"). "Remove from Split" (the menu equivalent of the ✕) is offered only for a real
      // member; `workroomContextMenu` drops the item and its divider on a nil closure. `closeName`
      // matches the chip's `workroomName ?? primaryLabel`. Attached AFTER `.gesture` so both share
      // the bar's `.contentShape`; secondary-click (menu) and the primary-button drag coexist.
      // The bar's own controls are separate hit targets, so a right-click landing directly on one may
      // not raise this menu (already true of the ✕ before issue #139 added its neighbours) — the
      // leading label region always does, and that is the region to aim for.
      .contextMenu {
        workroomContextMenu(
          store: store, sid: sid, target: target, closeName: workroomName ?? projectLabel,
          onRemoveFromSplit: multi ? onClose : nil)
      }
      // One unconditional slot. The "Directory not found" state and the withheld-during-setup state
      // both live INSIDE `TargetTerminalDetail`'s own ZStack, so nothing here ever swaps branches.
      TargetTerminalDetail(target: target, surfaceActive: focused)
    }
    // No border: the pane reads as a unit by a subtle raised fill over the `panel` base plus the
    // shadow + rounded corners (issue #110). The focused member's fill is accent-tinted so focus reads
    // as a colour; the rest take a faint neutral lift. Unconditional since issue #139 — a solo pane is
    // always the focused one, so it takes the accent fill with no special case.
    .background(WorkroomPaneCardBackground(focused: focused))
    .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
    .shadow(
      color: .black.opacity(focused ? 0.18 : 0.10), radius: focused ? 6 : 3, y: 2
    )
    // A clear gutter on every side — between the cards of a split, and between a solo card and the
    // window. The title bar sits at the pane's top, inside this inset.
    .padding(EdgeInsets(top: 4, leading: 4, bottom: 4, trailing: 4))
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("workroom.pane")
    // Roots aren't workrooms — say what this pane actually is (the chip makes the same distinction).
    .accessibilityLabel(
      Text(workroomName.map { "Workroom \($0)" } ?? "Project \(target.title)")
    )
    // Only meaningful with peers to be selected *among*: this trait tracks MODEL focus, and a solo
    // pane reporting `.isSelected` would say nothing while breaking how tests read it.
    .accessibilityAddTraits(focused && multi ? .isSelected : [])
  }

  /// The owning project's path. Handed to the title bar (rather than the `sid`) so a presentation view
  /// doesn't take a dependency on `SidebarID`, and so the lookup happens once for both the label and
  /// the run controls' `hasRunCommand` check.
  private var projectPath: String? { AppStore.projectPath(of: sid) }

  /// Which trailing controls the header shows — resolved in one pass so the group's divider can't
  /// disagree with the buttons on either side of it. The editor list is cached, so this is cheap enough
  /// to compute per render.
  private var toolbarControls: WorkroomPaneToolbarPresentation.Controls {
    WorkroomPaneToolbarPresentation.controls(
      isMissing: target.isMissing, projectPath: projectPath,
      hasEditor: !ExternalEditor.installed.isEmpty, multi: multi)
  }

  /// The project name — the chip's primary label format (`AppStore.projectPath` last component),
  /// matching `WorkroomTabChip.primaryLabel`. Empty only if the sid resolves no project.
  private var projectLabel: String {
    projectPath.map { ($0 as NSString).lastPathComponent } ?? ""
  }

  /// This member's own display name (nil for a project root) — the label-aware `target.title`,
  /// resolved through `WorkroomSplitTitlePresentation` so a relabel (issue #41) shows here
  /// immediately. Feeds both the title bar's visible text and its accessibility label (issue #113);
  /// NOT the raw `SidebarID` name, which never changes on relabel.
  private var workroomName: String? {
    WorkroomSplitTitlePresentation.workroomName(sid: sid, target: target)
  }

}

/// The pane card's fill. Its own view rather than an inline `.background(…)` value for two reasons: it
/// reads `\.controlActiveState` so the accent tint drops when the window isn't key (issue #139 — an
/// inactive window holding a saturated accent band reads as active and is against macOS convention),
/// and as a child it absorbs those activation re-renders itself, keeping them off `WorkroomPaneLeaf`
/// and the libghostty surface it hosts.
private struct WorkroomPaneCardBackground: View {
  let focused: Bool
  @Environment(\.controlActiveState) private var activeState
  private let theme = ThemeService.shared

  var body: some View {
    ZStack {
      theme.tokens.panel
      activeState == .inactive || !focused
        ? theme.tokens.splitGroupFill : theme.tokens.splitGroupFocusedFill
    }
  }
}

/// Which trailing controls a pane title bar offers. Pure and separate from the view (same rationale as

/// The coarse grouping a tree-sitter highlight capture maps to. We colour by category (≈12) rather
/// than per-capture (hundreds, grammar-specific) — `category(for:)` collapses any capture name.
enum SyntaxCategory: String, CaseIterable, Sendable {
  case keyword, function, type, namespace, constant, number, string, comment, variable, property,
    tag, attribute, punctuation, escape
}

// Focused-pane border + unfocused-pane scrim (issue #23 follow-up).
let focused: Color
let terminalDim: Color

// Workroom-split group fills (issue #110): the raised card behind a split member. The focused member
// is tinted by the accent so focus reads as a colour, not just a border; the rest take a faint neutral
// lift. Dedicated tokens (not the `hover`/`accentSoft` washes) so the group treatment can be tuned
// without dragging hover/selection along with it.
let splitGroupFill: Color  // fg @ 0.06 — unfocused member's raised fill
let splitGroupFocusedFill: Color  // accent @ 0.10 — focused member's accent-tinted fill

let colorScheme: ColorScheme

/// Resolve a parsed theme (or fall back to system colours) into the full token set.
init(
  preview: ThemePreview?,
  fallbackBackground: NSColor = .textBackgroundColor,
  fallbackForeground: NSColor = .textColor
) {
  let palette = preview?.palette ?? []
  func p(_ index: Int) -> NSColor? { palette.indices.contains(index) ? palette[index] : nil }

  let bgColor = preview?.background ?? fallbackBackground
  let fgColor = preview?.foreground ?? fallbackForeground
  let accentColor = p(4) ?? .controlAccentColor

  nsBg = bgColor
  nsFg = fgColor
  bg = Color(nsColor: bgColor)
  fg = Color(nsColor: fgColor)
  let panelColor =
    bgColor.usingColorSpace(.sRGB)?
    .blended(withFraction: 0.055, of: fgColor.usingColorSpace(.sRGB) ?? fgColor) ?? bgColor
  nsPanel = panelColor
  panel = Color(nsColor: panelColor)
  fgMuted = Color(nsColor: fgColor.withAlphaComponent(0.65))
  fgDim = Color(nsColor: fgColor.withAlphaComponent(0.40))
  surface = Color(nsColor: fgColor.withAlphaComponent(0.08))
  border = Color(nsColor: fgColor.withAlphaComponent(0.12))
  hover = Color(nsColor: fgColor.withAlphaComponent(0.06))
  tabActive = Color(nsColor: fgColor.withAlphaComponent(0.16))
  let fgSRGB = fgColor.usingColorSpace(.sRGB) ?? fgColor
  let accentSRGB = accentColor.usingColorSpace(.sRGB) ?? accentColor
  rowHover = Color(nsColor: panelColor.blended(withFraction: 0.06, of: fgSRGB) ?? panelColor)
  rowSelection = Color(
    nsColor: panelColor.blended(withFraction: 0.22, of: accentSRGB) ?? panelColor)

  accent = Color(nsColor: accentColor)
  nsAccent = accentColor
  accentSoft = Color(nsColor: accentColor.withAlphaComponent(0.10))
  accentForeground = Color(nsColor: Self.contrastingForeground(for: accentColor))
  warning = Color(nsColor: p(3) ?? .systemYellow)
  // ANSI colour 1 is red — the run-failure signal (chip + workroom dot + toast all share it). Same
  // palette slot as `diffRemoveFg`'s red, but a distinct semantic token so the two can't drift.
  failure = Color(nsColor: p(1) ?? .systemRed)
  // Orange = the palette's red blended halfway toward its yellow (no ANSI orange exists); falls
  // back to the system orange when a theme defines no palette.
  let conflictColor: NSColor = {
    guard let red = p(1)?.usingColorSpace(.sRGB), let yellow = p(3)?.usingColorSpace(.sRGB)
    else { return .systemOrange }
    return red.blended(withFraction: 0.5, of: yellow) ?? .systemOrange
  }()
  conflict = Color(nsColor: conflictColor)

  let addColor = p(2) ?? .systemGreen
  let removeColor = p(1) ?? .systemRed
  let hunkColor = p(6) ?? accentColor
  diffAddFg = Color(nsColor: addColor)
  diffRemoveFg = Color(nsColor: removeColor)
  nsDiffAddFg = addColor
  nsDiffRemoveFg = removeColor
  diffHunkFg = Color(nsColor: hunkColor)
  diffAddBg = Color(nsColor: addColor.withAlphaComponent(0.16))
  diffRemoveBg = Color(nsColor: removeColor.withAlphaComponent(0.16))
  diffHunkBg = Color(nsColor: hunkColor.withAlphaComponent(0.10))
  diffAddEmphasisBg = Color(nsColor: addColor.withAlphaComponent(0.40))
  diffRemoveEmphasisBg = Color(nsColor: removeColor.withAlphaComponent(0.40))

  // The opaque colour an added line's row composites to (theme bg + the 16% green tint) — the
  // background the contrast guard checks token colours against.
  nsAddBackgroundOpaque =
    bgColor.usingColorSpace(.sRGB)?
    .blended(withFraction: 0.16, of: addColor.usingColorSpace(.sRGB) ?? addColor) ?? bgColor

  // Capture → colour, derived from the ANSI palette so highlight colours track the terminal's
  // signature hues (and recompute on theme change with everything else). Falls back to system
  // colours when a theme defines no palette.
  let comment = fgColor.withAlphaComponent(0.45)
  syntaxByCategory = [
    .keyword: p(5) ?? .systemPurple,  // magenta
    .function: p(4) ?? .systemBlue,
    .type: p(3) ?? .systemYellow,
    .namespace: p(3) ?? .systemYellow,
    .constant: p(6) ?? .systemTeal,  // cyan
    .number: p(6) ?? .systemTeal,
    .string: p(2) ?? .systemGreen,
    .comment: comment,
    .variable: fgColor,
    .property: p(4) ?? .systemBlue,
    .tag: p(1) ?? .systemRed,
    .attribute: p(3) ?? .systemYellow,
    .punctuation: fgColor.withAlphaComponent(0.65),
    .escape: p(6) ?? .systemTeal,
  ]

  // The unfocused-pane scrim is the terminal's own background, so it's invisible *over* the
  // background and only washes the pane's text toward it (issue #23 follow-up). The focus border is
  // the SAME hairline as an unfocused pane (`border`, fg @ 0.12), just a little darker — so the
  // focused pane reads as "the focused one" without a heavy extra ring around it.
  terminalDim = Color(nsColor: bgColor)
  focused = Color(nsColor: fgColor.withAlphaComponent(0.3))
  splitGroupFill = Color(nsColor: fgColor.withAlphaComponent(0.06))
  splitGroupFocusedFill = Color(nsColor: accentColor.withAlphaComponent(0.10))

  // `perceivedBrightness`, not `luminance`: this is "does the background look light", which is the
  // encoded value. WCAG luminance is not perceptual — mid-grey linearizes to 0.216, so a threshold of
  // 0.5 against it would classify visibly light backgrounds as dark.

// surface composites its own layer. The scrim is the terminal's own background colour
// (`.terminalDim`) so it washes the text toward the background — the BG itself barely changes.
// The scrim is ALWAYS mounted and only its opacity animates (0↔0.3): conditionally inserting it
// would make a solo workroom's focus transition snap instead of fade. An activity flash lifts
// the dim so the pulse is visible on a backgrounded pane.
.overlay {
  RoundedRectangle(cornerRadius: TerminalPanelMetrics.cornerRadius)
    .fill(
      theme.tokens.terminalDim.opacity(
        PaneTreeView.shouldDim(
          multiPane: multiPane, surfaceActive: surfaceActive, focused: focused,
          flashing: flashing) ? 0.3 : 0)
    )
    .allowsHitTesting(false)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.1), value: flashing)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.07), value: focused)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.07), value: surfaceActive)
}
// A rounded border frames every terminal, the same in a split or solo: `borderColor` is the
// focus tint on the focused pane (a solo terminal is always focused, so it always gets it) and a
// neutral hairline on unfocused split panes — all at 1.5pt.
.overlay {
  RoundedRectangle(cornerRadius: TerminalPanelMetrics.cornerRadius)
    .strokeBorder(borderColor, lineWidth: 1.5)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: flashing)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.08), value: focused)
}
.overlay(alignment: .top) { handle }
// The one-time auto-diagnose opt-in — attached to the pane so it fires wherever the failure
// surfaces (the diagnosis itself lives in the detail-panel status bar / tab badge, issue #49).
.confirmationDialog(
  "Auto-diagnose failures from now on?",
  isPresented: Binding(
    get: { agentManager.autoOptInPromptTab == tabID },
    set: { if !$0 { agentManager.respondToAutoOptIn(enable: false) } }),

